  for (int i = 0, j = 1; j < numPoints; ++i, ++j) {
    fields[i] =
        new Triangle(
            fieldName,
            encodeLongitude(line.getLon(i)),
            encodeLatitude(line.getLat(i)),
            encodeLongitude(line.getLon(j)),
            encodeLatitude(line.getLat(j)),
            encodeLongitude(line.getLon(i)),
            encodeLatitude(line.getLat(i)));
  }
  return fields;
}

