      x = cX;
      bits = MAXY_MINX_MINY_MAXX_Y_X;
    } else if (minY == cY && maxX == cX) {
      y = bY;
      x = bX;
      bits = MAXY_MINX_Y_X_MINY_MAXX;
    } else {
      y = cY;
      x = bX;
      bits = MAXY_MINX_MINY_X_Y_MAXX;
