/** Relates an indexed line to this query for {@link QueryRelation#CONTAINS}. */
Component2D.WithinRelation relateContainsLine(ShapeField.DecodedTriangle triangle) {
  final Geometry queryGeometry = this.geometries[0];
  final Component2D query = this.queryComponent2D;
  if (queryGeometry == null) {
    throw new IllegalStateException("query geometry must not be null");
  }

  final double aLat = GeoEncodingUtils.decodeLatitude(triangle.aY);
  final double aLon = GeoEncodingUtils.decodeLongitude(triangle.aX);
  final double bLat = GeoEncodingUtils.decodeLatitude(triangle.bY);
  final double bLon = GeoEncodingUtils.decodeLongitude(triangle.bX);

  final double lineMinX = Math.min(aLon, bLon);
  final double lineMaxX = Math.max(aLon, bLon);
  final double lineMinY = Math.min(aLat, bLat);
  final double lineMaxY = Math.max(aLat, bLat);

  if (lineMaxX < query.getMinX()
      || lineMinX > query.getMaxX()
      || lineMaxY < query.getMinY()
      || lineMinY > query.getMaxY()) {
    return Component2D.WithinRelation.DISJOINT;
  }

  boolean fromShape = triangle.ab && triangle.aX >= GeoEncodingUtils.MIN_LON_ENCODED;

